
select "INVENTORY_ON_HAND"."INVENTORY_DATE" "Inventory_Date", "INVENTORY_ON_HAND"."BRANCH_PLANT" "Branch_Plant", "ITEM"."GLOBAL_BULK_ITEM" "Global_Bulk_Item", "ITEM"."BULK_ITEM" "Bulk_Item", "INVENTORY_ON_HAND_MEASURE"."ITEM_NUMBER_2ND" "C_2nd_Item_Number", "INVENTORY_ON_HAND_MEASURE"."LAST_RECEIPT_DATE_GREG" "Last_Receipt_Date", "INVENTORY_ON_HAND"."LOCATION" "Location", "INVENTORY_ON_HAND"."LOT_NUMBER" "Lot_Number", "ITEM_LOT_NUMBER_ALIAS"."ON_HAND_DATE" "On_Hand_Date", "ITEM_LOT_NUMBER_ALIAS"."LOT_EXPIRY_DATE" "Lot_Expiry_Date", "ITEM_LOT_NUMBER_ALIAS"."SELL_BY_DATE" "Sell_by_Date", "ITEM_LOT_NUMBER_ALIAS"."SUPPLIER_LOT_NUMBER" "Supplier_Lot_Number", "ITEM_LOT_NUMBER_ALIAS"."MEMO_LOT_1" "Memo_Lot_1", "ITEM_LOT_NUMBER_ALIAS"."MEMO_LOT_2" "Memo_Lot_2", "ITEM_LOT_NUMBER_ALIAS"."LOT_STATUS" "Lot_Status", "ITEM"."MASTER_PLANNING_FAMILY__IMPR" "Master_Planning_Family", sum("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_KG") "Quantity_on_Hand_KGs", sum("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND"*"INVENTORY_ON_HAND_MEASURE"."CONVERSION_FACTOR_LB") "Quantity_on_Hand_LBs", sum("INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND") "Quantity_on_Hand", "INVENTORY_ON_HAND_MEASURE"."UNIT_OF_MEASURE" "Primary_Unit_of_Measure"
 from "DW_LEGACY"."INVENTORY_ON_HAND" "INVENTORY_ON_HAND", "DW_LEGACY"."ITEM" "ITEM", "DW_LEGACY"."INVENTORY_ON_HAND_MEASURES" "INVENTORY_ON_HAND_MEASURE", "DW_LEGACY"."ITEM_LOT_NUMBERS" "ITEM_LOT_NUMBER_ALIAS"
 where "INVENTORY_ON_HAND_MEASURE"."QUANTITY_ON_HAND">0 and "ITEM"."GLOBAL_BULK_ITEM" in (N'ESC5200') and "INVENTORY_ON_HAND"."INVENTORY_DATE"=CAST( ( :PQ1 ) AS TIMESTAMP ) and "INVENTORY_ON_HAND"."INVENTORY_ON_HAND_SID"="INVENTORY_ON_HAND_MEASURE"."INVENTORY_ON_HAND_SID" and "INVENTORY_ON_HAND_MEASURE"."INVENTORY_ON_HAND__ITEM_SID"="ITEM"."ITEM_SID" and "ITEM_LOT_NUMBER_ALIAS"."ITEM_LOT_NUMBERS_SID"="INVENTORY_ON_HAND_MEASURE"."INVENTORY_ON_HAND__ITEM__SID1"
 group by "INVENTORY_ON_HAND"."INVENTORY_DATE", "INVENTORY_ON_HAND"."BRANCH_PLANT", "ITEM"."GLOBAL_BULK_ITEM", "ITEM"."BULK_ITEM", "INVENTORY_ON_HAND_MEASURE"."ITEM_NUMBER_2ND", "INVENTORY_ON_HAND_MEASURE"."LAST_RECEIPT_DATE_GREG", "INVENTORY_ON_HAND"."LOCATION", "INVENTORY_ON_HAND"."LOT_NUMBER", "ITEM_LOT_NUMBER_ALIAS"."ON_HAND_DATE", "ITEM_LOT_NUMBER_ALIAS"."LOT_EXPIRY_DATE", "ITEM_LOT_NUMBER_ALIAS"."SELL_BY_DATE", "ITEM_LOT_NUMBER_ALIAS"."SUPPLIER_LOT_NUMBER", "ITEM_LOT_NUMBER_ALIAS"."MEMO_LOT_1", "ITEM_LOT_NUMBER_ALIAS"."MEMO_LOT_2", "ITEM_LOT_NUMBER_ALIAS"."LOT_STATUS", "ITEM"."MASTER_PLANNING_FAMILY__IMPR", "INVENTORY_ON_HAND_MEASURE"."UNIT_OF_MEASURE"
 order by "Branch_Plant" asc nulls last, "Last_Receipt_Date" asc nulls last



